    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Recover the repeating color order from horizontally adjacent cells.
    colors = {v for row in grid for v in row if v not in (0, 2, 4, 6, 8)}
    if not colors:
        return out
    edges = {}
    for row in grid:
        for a, b in zip(row, row[1:]):
            if a in colors and b in colors and a != b:
                edges[a, b] = edges.get((a, b), 0) + 1

    start = max(colors, key=lambda a: sum(n for (x, _), n in edges.items() if x == a))
    cycle = [start]
    while len(cycle) < len(colors):
        choices = [(n, b) for (a, b), n in edges.items()
                   if a == cycle[-1] and b not in cycle]
        if not choices:
            break
        cycle.append(max(choices)[1])
    cycle += sorted(colors - set(cycle))
    p = len(cycle)

    # The pattern advances one position with each row and column; find its
    # phase from the observed cells.
    offsets = [0] * p
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v in cycle:
                offsets[(cycle.index(v) - r - c) % p] += 1
    offset = max(range(p), key=lambda k: offsets[k])

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = cycle[(r + c + offset) % p]
    return out
